/// A grid's fixed track count from `prop` (`WIDTH` = columns for vertical
/// grids, `HEIGHT` = rows for horizontal grids): a positive finite Fixed value
/// pins the count; `FILL`/absent → auto-fit (`None`).
fn grid_count(node: &Node, prop: u16) -> Option<u32> {
    let v = node.f32_property(prop, -1.0);
    if v <= 0.0 {
        None
    } else {
        Some(v.round() as u32)
    }
}

/// A vertical grid's column count from `WIDTH` (spec §Grid).
fn grid_columns(node: &Node) -> Option<u32> {
    grid_count(node, property_id::WIDTH)
}

/// A horizontal grid's (`LAZY_HGRID`) row count from `HEIGHT`.
fn grid_rows(node: &Node) -> Option<u32> {
    grid_count(node, property_id::HEIGHT)
}
```

Wait — but for GRID (static), both WIDTH and HEIGHT are counts (columns and rows). For GRID: columns from WIDTH, rows from HEIGHT. For LAZY_VGRID: columns from WIDTH only. For LAZY_HGRID: rows from HEIGHT only.

New `grid_style`:
```rust
/// Inline grid CSS: `display:grid`, `justify-items`/`align-items` from
/// `ALIGNMENT` (cells position within their tracks; default Leading/start),
/// and the fixed track templates — `WIDTH` columns (GRID/LAZY_VGRID),
/// `HEIGHT` rows (GRID/LAZY_HGRID).
fn grid_style(node: &Node) -> String {
    let horizontal = node.component == component_type::LAZY_HGRID;
    let align = grid_align_pos(node);
    let mut css = format!("display:grid;justify-items:{align};align-items:{align};");
    match node.component {
        component_type::LAZY_HGRID => {
            if let Some(n) = grid_rows(node) {
                css.push_str(&format!("grid-template-rows:repeat({n},1fr);"));
            }
            css.push_str("grid-auto-flow:column;grid-auto-columns:1fr;");
        }
        component_type::GRID => {
            if let Some(n) = grid_columns(node) {
                css.push_str(&format!("grid-template-columns:repeat({n},1fr);"));
            }
            if let Some(n) = grid_rows(node) {
                css.push_str(&format!("grid-template-rows:repeat({n},1fr);"));
            }
        }
        _ => { // LAZY_VGRID
            if let Some(n) = grid_columns(node) {
                css.push_str(&format!("grid-template-columns:repeat({n},1fr);"));
            }
        }
    }
    css
}

/// The grid `ALIGNMENT` position token (start/center/end, default start).
fn grid_align_pos(node: &Node) -> &'static str {
    match node.f32_property(property_id::ALIGNMENT, 3.0) as u8 {
        1 => "center",
        2 => "end",
        _ => "start",
    }
}
```

