         byte[] wire = FrameCodec.encodeFrame(sink.frame());
         Frame decoded = FrameCodec.decodeFrame(wire);
         assertEquals(sink.frame().opcodes(), decoded.opcodes());
         assertTrue(new String(decoded.strings()).contains("Hello Pathland"));
