     pub const SET_TEXT: u8 = 0x03;
     /// **Draft.** `A=nodeId, B=days since epoch (I32), C=millis of day (U32)` —
     /// set a node's date value (e.g. a `DATE_PICKER`); see
     /// `spec/PRIMITIVES.md` / `spec/OPCODE.md`.
     pub const SET_DATE: u8 = 0x04;
