         let html = HtmlRenderer::new().render_document(&opcodes, &strings, 1);
         assert!(
             html.contains("style=\"display:-webkit-box;-webkit-line-clamp:1;-webkit-box-orient:vertical;\""),
             "a positive LINE_LIMIT clamps the text to N lines: {html}"
