         assert!(
             html.contains("<style data-pathland-tokens>:root{--pl-color-primary:rgba(37,99,235,1);}"),
             "base rule inside the token style element: {html}"
         );
         assert!(
             html.contains("rgba(96,165,250,1);}}</style>"),
