New grid branch needs to:
1. Detect explicit rows: any direct child with component GRID_ROW.
2. Build the flattened shell list: for each direct child, if GRID_ROW → its child shells; else the shell itself.
3. If explicit rows: compute effective columns (from el.style.gridTemplateColumns parse, or widest row), set placements (gridRow/gridColumn on shells), and set gridTemplateColumns to repeat(widest,1fr) if absent.
4. Always set justify/align on each shell.

Let me write it:

```ts
} else if (isGridComponent(comp)) {
  // Explicit rows (spec §GridRow): a grid's children are cells or GRID_ROWs.
  const token = el.style.alignItems || "start";
  const children = Array.from(el.children).filter((c): c is HTMLElement => c instanceof HTMLElement);
  const explicitRows = children.some((c) => componentByNode.get(c) === COMPONENT_GRID_ROW);
  // Flatten to (shell, row, col) when rows are explicit.
  const parseCount = (s: string): number | null => {
    const m = /repeat\(\s*(\d+)/.exec(s);
    return m ? Number(m[1]) : null;
  };
  let cols = parseCount(el.style.gridTemplateColumns);
  if (explicitRows) {
    let width = cols ?? 0;
    let run = 0;
    for (const c of children) {
      if (componentByNode.get(c) === COMPONENT_GRID_ROW) {
        width = Math.max(width, c.children.length);
        run = 0;
      } else {
        run += 1;
        width = Math.max(width, run);
      }
    }
    width = Math.max(width, 1);
    if (cols === null) {
      el.style.gridTemplateColumns = `repeat(${width},1fr)`;
      cols = width;
    }
    const columns = cols ?? width;
    let row = 0, col = 0;
    for (const c of children) {
      if (componentByNode.get(c) === COMPONENT_GRID_ROW) {
        if (col > 0) row += 1;
        col = 0;
        for (const shell of Array.from(c.children).filter((s): s is HTMLElement => s instanceof HTMLElement)) {
          shell.style.gridRow = String(row + 1);
          shell.style.gridColumn = String(col + 1);
          shell.style.justifySelf = fillsAxis(shell, true, false) ? "stretch" : token;
          shell.style.alignSelf = fillsAxis(shell, false, false) ? "stretch" : token;
          col += 1;
        }
        row += 1;
        col = 0;
      } else {
        if (col >= columns) { row += 1; col = 0; }
        c.style.gridRow = String(row + 1);
        c.style.gridColumn = String(col + 1);
        c.style.justifySelf = fillsAxis(c, true, false) ? "stretch" : token;
        c.style.alignSelf = fillsAxis(c, false, false) ? "stretch" : token;
        col += 1;
      }
    }
  } else {
    for (const w of children) {
      w.style.justifySelf = fillsAxis(w, true, false) ? "stretch" : token;
      w.style.alignSelf = fillsAxis(w, false, false) ? "stretch" : token;
    }
  }
}
```

