 /// both mean the default hug positioning (never stretch), so they yield `None`
 /// (LAYOUT.md).
 pub fn stack_align_option(node: &HostNode) -> Option<Align> {
     node.properties
         .get(&property_id::ALIGNMENT)
         .map(|raw| align_from(*raw))
         .filter(|a| *a != Align::Fill)
