 /// MODIFIERS.md) to the pango ellipsize position (SwiftUI `.truncationMode`
 /// parity).
 pub fn ellipsize_from(mode: u8) -> pango::EllipsizeMode {
     match mode {
         0 => pango::EllipsizeMode::Start,
         1 => pango::EllipsizeMode::Middle,
         _ => pango::EllipsizeMode::End,
