         for ct in [VSTACK, HSTACK, GRID, SCROLLVIEW, ZSTACK] {
             assert!(is_container(ct), "{ct:#x} should be a container");
         }
         for ct in [TEXT, BUTTON, SPACER, IMAGE, TOGGLE, SLIDER] {
             assert!(!is_container(ct), "{ct:#x} should not be a container");
         }
     }

