 /// to the `size::FILL` sentinel; finite values pass through unchanged.
 fn fill_or(v: f32) -> f32 {
     if v.is_infinite() {
         pathland_core::size::FILL
     } else {
         v
     }
 }

 impl ViewModifier for PointerEvents {
     fn apply(&self, node: &mut Node) {
