             .copied()
             .unwrap_or(0);
         node.properties.insert(
             property_id::EVENT_LISTENERS,
             existing
                 | pathland_core::listener::POINTER_DOWN
                 | pathland_core::listener::POINTER_UP,
         );
         node.gestures.push(Gesture::Tap(self.0.clone()));
     }
 }

