                     let max = f64::from(node.f32_property(property_id::MAX_VALUE, 1.0));
                     let step = f64::from(node.f32_property(property_id::STEP_VALUE, 0.0));
                     let value = f64::from(node.f32_property(property_id::VALUE, 0.0));
